<?php
namespace Srms;
final class BillingRoll {
 public static function upload(array $file): string {Auth::staff();if(($file['error']??4)!==0||!is_uploaded_file($file['tmp_name']??'')||!in_array(strtolower(pathinfo($file['name'],PATHINFO_EXTENSION)),['geojson','json'],true))throw new \DomainException('Choose a GeoJSON file.');return self::prepare($file['tmp_name'],basename($file['name']));}
 public static function read(string $path): array {if(!is_file($path)||filesize($path)>15*1024*1024)throw new \DomainException('Use a GeoJSON file up to 15 MB.');$data=json_decode(file_get_contents($path),true,64,JSON_THROW_ON_ERROR);if(($data['type']??'')!=='FeatureCollection'||!is_array($data['features']??null)||!array_is_list($data['features'])||!count($data['features'])||count($data['features'])>10000)throw new \DomainException('Use a FeatureCollection with 1 to 10,000 features.');return $data['features'];}
 public static function normalize(array $feature): array {if(($feature['type']??'')!=='Feature')throw new \DomainException('Each entry must be a Feature.');$source=$feature['properties']??[];if(!is_array($source)||!is_string($source['Account']??null))throw new \DomainException('Each parcel requires its permanent Account number.');$number=AccountNumber::validate($source['Account']);$g=$feature['geometry']??[];if(!is_array($g)||!in_array($g['type']??'',['Polygon','MultiPolygon'],true))throw new \DomainException('Parcel boundaries must be polygons.');return ['Account'=>$number,'FID'=>$source['FID']??null,'geometry'=>json_decode(Registry::geometry(json_encode($g,JSON_THROW_ON_ERROR)),true)];}
 private static function existing(array $row,bool $lock=false): ?array {$p=Database::one('SELECT * FROM parcel_accounts WHERE account_number=?'.($lock?' FOR UPDATE':''),[$row['Account']]);if($p&&$p['boundary_geojson']){$g=json_decode($p['boundary_geojson'],true);if(is_string($g))$g=json_decode($g,true);if($g!=$row['geometry'])throw new \DomainException('Account already exists with a different boundary. Existing records will not be overwritten.');}return $p;}
 public static function prepare(string $path,?string $filename=null): string {Auth::staff();$features=self::read($path);return Database::transaction(function()use($path,$filename,$features){$batch=Database::insert('import_batches',['source_filename'=>basename($filename??$path),'entity_type'=>'billing_roll','status'=>'validated','created_by'=>Auth::user()['id'],'file_hash'=>hash_file('sha256',$path)]);$seen=[];$good=0;$bad=0;foreach($features as $i=>$feature){$row=[];$error=null;try{if(!is_array($feature))throw new \DomainException('Invalid feature.');$row=self::normalize($feature);if(isset($seen[$row['Account']]))throw new \DomainException('Duplicate Account in source.');$seen[$row['Account']]=true;$p=self::existing($row);$row['preview_action']=$p?'skip_existing':'create_parcel';$good++;}catch(\DomainException|\JsonException $e){$error=$e->getMessage();$bad++;}Database::insert('import_rows',['batch_id'=>$batch,'row_number'=>$i+1,'row_data_json'=>json_encode(['source'=>$feature,'validated'=>$row],JSON_THROW_ON_ERROR),'status'=>$error?'invalid':'valid','validation_errors'=>$error]);}Database::update('import_batches',$batch,['total_rows'=>$good+$bad,'valid_rows'=>$good,'invalid_rows'=>$bad]);Audit::log('billing_roll_validated','import_batches',$batch,null,['valid'=>$good,'invalid'=>$bad]);return $batch;});}
 public static function commit(string $id): int {Auth::admin();return Database::transaction(function()use($id){$batch=Database::lock('import_batches',$id);if($batch['entity_type']!=='billing_roll'||$batch['invalid_rows']>0||!in_array($batch['status'],['validated','processing','failed','completed'],true))throw new \DomainException('Only a valid Billing Roll batch can be approved.');if($batch['status']==='completed')return 0;Database::update('import_batches',$id,['status'=>'processing','approved_by'=>$batch['approved_by']??Auth::user()['id'],'approved_at'=>$batch['approved_at']??date('Y-m-d H:i:s'),'started_at'=>$batch['started_at']??date('Y-m-d H:i:s')]);$rows=Database::all(Database::page("SELECT * FROM import_rows WHERE batch_id=? AND status='valid' ORDER BY row_number",1,(int)Settings::get('import_chunk_rows','100')),[$id]);foreach($rows as $r){$source=json_decode($r['row_data_json'],true,64,JSON_THROW_ON_ERROR);$row=self::normalize($source['source']);$p=self::existing($row,true);$target=$p?$row['Account']:Registry::save('parcels',['account_number'=>$row['Account'],'boundary_geojson'=>json_encode($row['geometry'],JSON_THROW_ON_ERROR),'locality'=>$source['source']['properties']['locality']??null,'notes'=>'Imported source Account '.$row['Account'].'; batch '.$id]);Database::update('import_rows',$r['id'],['status'=>$p?'skipped':'imported','target_entity_id'=>$target,'processed_at'=>date('Y-m-d H:i:s'),'validation_errors'=>null]);}$remaining=(int)Database::scalar("SELECT COUNT(*) FROM import_rows WHERE batch_id=? AND status NOT IN ('imported','skipped')",[$id]);if(!$remaining)Database::update('import_batches',$id,['status'=>'completed','completed_at'=>date('Y-m-d H:i:s')]);Audit::log('billing_roll_chunk_committed','import_batches',$id,null,['processed'=>count($rows),'remaining'=>$remaining]);return $remaining;});}
}